18	)
19	
20	// DEVDESK-335 step 4: a silent end of the path is one row, not a wall of rows.
21	
22	const lastAnswerTag = " · last to answer"
23	
24	// nrHops builds TTLs 1..total: routers up to and including routers, then the
25	// given kind (HopSilent by default) for the rest.
26	func nrHops(total, routers int, tail ...nettrace.HopKind) []nettrace.Hop {
27		kind := nettrace.HopSilent
28		if len(tail) > 0 {
29			kind = tail[0]
30		}
31		out := make([]nettrace.Hop, 0, total)
32		for ttl := 1; ttl <= total; ttl++ {
33			if ttl <= routers {
34				out = append(out, nettrace.Hop{TTL: ttl, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr(fmt.Sprintf("10.0.0.%d", ttl))})
35				continue
36			}
37			out = append(out, nettrace.Hop{TTL: ttl, Kind: kind})
38		}
39		return out
40	}
41	
42	func nrResult(o nettrace.Outcome, hops []nettrace.Hop) *nettrace.Result {
43		return &nettrace.Result{Outcome: o, Hops: hops}
44	}
45	
46	// nrRows is pathSteps + withNoResponse for res, as refreshSteps composes them.
47	func nrRows(res *nettrace.Result) []pathStep {
48		var hops []nettrace.Hop
49		if res != nil {
50			hops = res.Hops
51		}
52		route := &pathRoute{Known: true, Interface: "eth0", Gateway: netip.MustParseAddr("10.0.0.1")}
53		return withNoResponse(pathSteps(nil, route, hops), res)
54	}
55	
56	func nrHopRows(steps []pathStep) []pathStep {
57		var out []pathStep
58		for _, s := range steps {
59			if s.Kind >= stepHop {
60				out = append(out, s)
61			}
62		}
63		return out
64	}
65	
66	// nrCells is "hop|step|address|rtt" per hop-level row.
67	func nrCells(steps []pathStep) []string {
68		var out []string
69		for _, s := range nrHopRows(steps) {
70			out = append(out, s.hopCell()+"|"+s.stepCell()+"|"+s.addressCell()+"|"+s.rttCell())
71		}
72		return out
73	}
74	
75	func TestWithNoResponse(t *testing.T) {
76		deadlineMixed := nrHops(8, 3)
77		deadlineMixed[5].Kind = nettrace.HopUnresolved
78		deadlineMixed[7].Kind = nettrace.HopUnresolved
79		withError := nrHops(6, 2)
80		withError[2] = nettrace.Hop{TTL: 3, Kind: nettrace.HopError, Err: errors.New("send failed")}
81		middle := nrHops(6, 5)
82		middle[2].Kind = nettrace.HopSilent
83		middle[2].Addr = netip.Addr{}
84	
85		tests := []struct {
86			name     string
87			res      *nettrace.Result
88			wantTail pathTail
89			wantOK   bool
90			wantRows int    // hop-level rows after grouping
91			wantLast string // address cell of the last-to-answer row ("" = none)
92			wantAddr string // address cell of the grouped row
93			wantHop  string // hop cell of the grouped row
94		}{
95			{"1 to 3 routers then silent", nrResult(nettrace.OutcomeMaxHops, nrHops(30, 3)),
96				pathTail{First: 4, Last: 30, Anchor: 3}, true, 4, "10.0.0.3" + lastAnswerTag,
97				"no response beyond hop 3 (hops 4 to 30)", "4+"},
98			{"criterion 3: one router then silent", nrResult(nettrace.OutcomeMaxHops, nrHops(30, 1)),
99				pathTail{First: 2, Last: 30, Anchor: 1}, true, 2, "10.0.0.1" + lastAnswerTag,
100				"no response beyond hop 1 (hops 2 to 30)", "2+"},
101			{"nothing answered", nrResult(nettrace.OutcomeMaxHops, nrHops(30, 0)),
102				pathTail{First: 1, Last: 30}, true, 1, "",
103				"no response from any hop (hops 1 to 30)", "1+"},
104			{"a silent hop in the middle stays", nrResult(nettrace.OutcomeMaxHops, middle),
105				pathTail{First: 6, Last: 6, Anchor: 5}, true, 6, "10.0.0.5" + lastAnswerTag,
106				"no response beyond hop 5 (hop 6)", "6"},
107			{"single silent hop at the end", nrResult(nettrace.OutcomeMaxHops, nrHops(30, 29)),
108				pathTail{First: 30, Last: 30, Anchor: 29}, true, 30, "10.0.0.29" + lastAnswerTag,
109				"no response beyond hop 29 (hop 30)", "30"},
110			{"router on the last TTL", nrResult(nettrace.OutcomeMaxHops, nrHops(30, 30)),
111				pathTail{}, false, 30, "", "", ""},
112			{"deadline, unresolved mixed with silent", nrResult(nettrace.OutcomeDeadline, deadlineMixed),
113				pathTail{First: 4, Last: 8, Anchor: 3}, true, 4, "10.0.0.3" + lastAnswerTag,
114				"no response beyond hop 3 (hops 4 to 8)", "4+"},
115			{"an error row before the silent end stays", nrResult(nettrace.OutcomeMaxHops, withError),
116				pathTail{First: 4, Last: 6, Anchor: 2}, true, 4, "10.0.0.2" + lastAnswerTag,
117				"no response beyond hop 2 (hops 4 to 6)", "4+"},
118		}
119		for _, tc := range tests {
120			t.Run(tc.name, func(t *testing.T) {
121				tail, ok := silentTail(tc.res)
122				if ok != tc.wantOK || (ok && tail != tc.wantTail) {
123					t.Fatalf("silentTail = %+v, %v; want %+v, %v", tail, ok, tc.wantTail, tc.wantOK)
124				}
125				hops := nrHopRows(nrRows(tc.res))
126				if len(hops) != tc.wantRows {
127					t.Fatalf("hop-level rows = %d (%q), want %d", len(hops), nrCells(nrRows(tc.res)), tc.wantRows)
128				}
129				if !tc.wantOK {
130					for _, s := range hops {
131						if s.Kind == stepNoResponse || s.LastAnswer || strings.Contains(s.addressCell(), lastAnswerTag) {
132							t.Errorf("row %q carries a mark, want none", s.addressCell())
133						}
134					}
135					return
136				}
137				g := hops[len(hops)-1]
138				if g.Kind != stepNoResponse || g.Tail != tc.wantTail {
139					t.Fatalf("last row = kind %v tail %+v, want a stepNoResponse with %+v", g.Kind, g.Tail, tc.wantTail)
140				}
141				if g.hopCell() != tc.wantHop || g.stepCell() != "silent" || g.rttCell() != "-" || g.addressCell() != tc.wantAddr {
142					t.Errorf("cells = %q|%q|%q|%q, want %q|silent|%q|-", g.hopCell(), g.stepCell(), g.addressCell(), g.rttCell(), tc.wantHop, tc.wantAddr)
143				}
144				var marked []string
145				for _, s := range hops {
146					if s.LastAnswer {
147						marked = append(marked, s.addressCell())
148					}
149				}
150				var want []string
151				if tc.wantLast != "" {
152					want = []string{tc.wantLast}
153				}
154				if !reflect.DeepEqual(marked, want) {
155					t.Errorf("last-to-answer rows = %q, want %q", marked, want)
156				}
157			})
158		}
159	}
