161	func TestWithNoResponseLeavesOtherOutcomesAlone(t *testing.T) {
162		for _, o := range []nettrace.Outcome{nettrace.OutcomeReached, nettrace.OutcomeUnreachable, nettrace.OutcomeCancelled} {
163			t.Run(o.String(), func(t *testing.T) {
164				res := nrResult(o, nrHops(10, 3))
165				steps := pathSteps(nil, nil, res.Hops)
166				if got := withNoResponse(steps, res); !reflect.DeepEqual(got, steps) {
167					t.Errorf("rows changed for %v", o)
168				}
169				if _, ok := silentTail(res); ok {
170					t.Errorf("silentTail ok for %v, want false", o)
171				}
172			})
173		}
174		steps := pathSteps(nil, nil, nrHops(10, 3))
175		if got := withNoResponse(steps, nil); !reflect.DeepEqual(got, steps) {
176			t.Errorf("nil result changed the rows")
177		}
178		if _, ok := silentTail(nil); ok {
179			t.Errorf("silentTail(nil) ok, want false")
180		}
