183	func TestWithNoResponseDoesNotModifyItsInputs(t *testing.T) {
184		res := nrResult(nettrace.OutcomeMaxHops, nrHops(30, 2))
185		steps := pathSteps(nil, &pathRoute{Known: true}, res.Hops)
186		stepsBefore := append([]pathStep(nil), steps...)
187		hopsBefore := append([]nettrace.Hop(nil), res.Hops...)
188		_ = withNoResponse(steps, res)
189		if !reflect.DeepEqual(steps, stepsBefore) || !reflect.DeepEqual(res.Hops, hopsBefore) {
190			t.Errorf("withNoResponse modified its input")
191		}
