194	// Criterion 3: no wording that says the target is down.
195	func TestNoResponseNeverSaysDown(t *testing.T) {
196		res := nrResult(nettrace.OutcomeMaxHops, nrHops(30, 1))
197		pm := resolvedWith(t, lanRoute(), nil)
