210		for _, w := range []string{"down", "offline", "failed", "unreachable"} {
211			if strings.Contains(joined, w) {
212				t.Errorf("table or header contains %q:\n%s", w, joined)
213			}
214		}
215		if !strings.Contains(joined, "no response beyond hop 1 (hops 2 to 30)") {
216			t.Errorf("grouped row missing:\n%s", joined)
217		}
218	}
