236	func TestHopCellOfTheGroupedRowFitsTheColumn(t *testing.T) {
237		for _, first := range []int{1, 9, 12, 30} {
238			for _, last := range []int{first, 30} {
239				s := pathStep{Kind: stepNoResponse, Tail: pathTail{First: first, Last: last}}
240				if w := ansi.StringWidth(s.hopCell()); w > 3 {
