250	// The stream shows hops one by one; only the done message groups them.
251	func TestPathFlowSilentEndIsGroupedOnDone(t *testing.T) {
252		final := nrHops(30, 3)
253		f := &fakeEngine{traceFn: func(_ context.Context, a netip.Addr, _ nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error) {
254			for _, h := range final {
255				onHop(h)
256			}
257			return nettrace.Result{Target: a, Outcome: nettrace.OutcomeMaxHops, Hops: final}, nil
258		}}
259		pm := newPathModel(f.engine())
260		pm.resize(120, 40)
261		pm, _ = pmFeed(t, pm, testutil.Type("1.1.1.1")...)
262		pm, _ = pmFeed(t, pm, testutil.Key("enter"))
263	
264		ch := make(chan tea.Msg, pathChanCap)
265		producePath(context.Background(), pm.gen, pm.target, hostSource(), pm.resolveTimeout, pm.engine, ch)
266		streamed := -1
267		for msg := range ch {
268			pm, _ = pmFeed(t, pm, msg)
269			if pm.result == nil {
270				streamed = len(pm.table.Items())
271			}
272		}
273		if pm.result == nil {
274			t.Fatal("no result after the done message")
275		}
276		if streamed < 30 {
277			t.Errorf("rows while streaming = %d, want every hop shown", streamed)
278		}
279		want := []string{
280			"1|router|10.0.0.1|-", "2|router|10.0.0.2|-",
281			"3|router|10.0.0.3" + lastAnswerTag + "|-",
282			"4+|silent|no response beyond hop 3 (hops 4 to 30)|-",
283		}
284		if got := nrCells(pm.table.Items()); !reflect.DeepEqual(got, want) {
285			t.Errorf("hop rows = %q, want %q", got, want)
286		}
287		for _, h := range pm.headerInfo() {
288			if h.Key == "Path" && h.Value != "No answer from the target within 30 hops" {
289				t.Errorf("Path header = %q, want it unchanged", h.Value)
290			}
