22	const lastAnswerTag = " · last to answer"
23	
24	// nrHops builds TTLs 1..total: routers up to and including routers, then the
25	// given kind (HopSilent by default) for the rest.
26	func nrHops(total, routers int, tail ...nettrace.HopKind) []nettrace.Hop {
27		kind := nettrace.HopSilent
28		if len(tail) > 0 {
29			kind = tail[0]
30		}
31		out := make([]nettrace.Hop, 0, total)
32		for ttl := 1; ttl <= total; ttl++ {
33			if ttl <= routers {
34				out = append(out, nettrace.Hop{TTL: ttl, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr(fmt.Sprintf("10.0.0.%d", ttl))})
35				continue
36			}
37			out = append(out, nettrace.Hop{TTL: ttl, Kind: kind})
38		}
39		return out
40	}
41	
42	func nrResult(o nettrace.Outcome, hops []nettrace.Hop) *nettrace.Result {
43		return &nettrace.Result{Outcome: o, Hops: hops}
44	}
45	
46	// nrRows is pathSteps + withNoResponse for res, as refreshSteps composes them.
47	func nrRows(res *nettrace.Result) []pathStep {
48		var hops []nettrace.Hop
49		if res != nil {
50			hops = res.Hops
51		}
52		route := &pathRoute{Known: true, Interface: "eth0", Gateway: netip.MustParseAddr("10.0.0.1")}
53		return withNoResponse(pathSteps(nil, route, hops), res)
54	}
55	
56	func nrHopRows(steps []pathStep) []pathStep {
57		var out []pathStep
58		for _, s := range steps {
59			if s.Kind >= stepHop {
60				out = append(out, s)
61			}
62		}
63		return out
64	}
65	
66	// nrCells is "hop|step|address|rtt" per hop-level row.
67	func nrCells(steps []pathStep) []string {
68		var out []string
69		for _, s := range nrHopRows(steps) {
70			out = append(out, s.hopCell()+"|"+s.stepCell()+"|"+s.addressCell()+"|"+s.rttCell())
71		}
72		return out
73	}
