1	package netdiag
2	
3	import (
4		"fmt"
5		"net"
6		"net/netip"
7		"strconv"
8		"time"
9	
10		"github.com/anthnel/devdesk/internal/netcheck"
11		"github.com/anthnel/devdesk/internal/nettrace"
12		"github.com/anthnel/devdesk/internal/wslenv"
13	)
14	
15	// pathStepKind says which kind of row a pathStep is.
16	type pathStepKind int
17	
18	// The kinds of row, in the order the column shows them.
19	const (
20		stepContainer pathStepKind = iota
21		stepNetwork
22		stepBridge
23		stepEngine
24		stepSource
25		stepInterface
26		stepGateway
27		stepTrace
28		stepHop
29	)
30	
31	// pathRoute is the way out of this machine for the traced address.
32	type pathRoute struct {
33		Known     bool // false: the lookup failed; interface and gateway are undetermined
34		NoRoute   bool // the lookup proved this machine has no route (Known stays false)
35		Interface string
36		Source    netip.Addr // invalid: the stack did not say
37		Gateway   netip.Addr // invalid: directly connected
38	}
39	
40	// pathStep is one row of the Path column.
41	type pathStep struct {
42		Kind      pathStepKind
43		Container pathContainer // stepContainer, stepNetwork, stepBridge, stepEngine, stepTrace
44		Route     pathRoute     // stepInterface, stepGateway
45		Hop       nettrace.Hop  // stepHop
46		WSL       wslenv.Info   // stepSource: set by withWSL
47		// WindowsHost marks the gateway row and the TTL 1 hop as the Windows
48		// virtual switch (WSL2 NAT mode only): set by withWSL.
49		WindowsHost bool
50	}
51	
52	const (
53		sourceLabel       = "this machine"
54		routeUndetermined = "undetermined"
55		routeNone         = "no route"
56		gatewayNone       = "-"
57		gatewayDirect     = "directly connected"
58	)
59	
60	// newPathRoute converts a route lookup into a pathRoute. A failed lookup
61	// discards whatever the hop holds; a no-route failure is told apart from any
62	// other, which stays undetermined. Addresses are unmapped to IPv4 when they can be.
63	func newPathRoute(hop netcheck.RouteHop, err error) pathRoute {
64		if err != nil {
65			return pathRoute{NoRoute: nettrace.IsNoRoute(err)}
66		}
67		return pathRoute{
68			Known:     true,
69			Interface: hop.Interface,
70			Source:    addrFromIP(hop.Source),
71			Gateway:   addrFromIP(hop.Gateway),
72		}
73	}
74	
75	// addrFromIP returns ip as an unmapped netip.Addr, or the zero Addr for a nil or invalid ip.
76	func addrFromIP(ip net.IP) netip.Addr {
77		addr, ok := netip.AddrFromSlice(ip)
78		if !ok {
79			return netip.Addr{}
80		}
81		return addr.Unmap()
82	}
83	
84	// pathSteps returns the rows of the Path column: the source, then the
85	// interface and gateway when route is not nil, then the hops as selected by
86	// visiblePathHops. It returns nil while neither a route nor a hop exists.
87	// Neither input is modified.
88	func pathSteps(ctr *pathContainer, route *pathRoute, hops []nettrace.Hop) []pathStep {
89		if ctr == nil && route == nil && len(hops) == 0 {
90			return nil
91		}
92		var steps []pathStep
93		if ctr != nil {
94			steps = append(steps,
95				pathStep{Kind: stepContainer, Container: *ctr},
96				pathStep{Kind: stepNetwork, Container: *ctr},
97			)
98			switch {
99			case ctr.Bridge != "":
100				steps = append(steps, pathStep{Kind: stepBridge, Container: *ctr})
101			case ctr.Engine != engineNone:
102				steps = append(steps, pathStep{Kind: stepEngine, Container: *ctr})
103			}
104		}
105		steps = append(steps, pathStep{Kind: stepSource})
106		if route != nil {
107			steps = append(steps,
108				pathStep{Kind: stepInterface, Route: *route},
109				pathStep{Kind: stepGateway, Route: *route},
110			)
111		}
112		if ctr != nil {
113			steps = append(steps, pathStep{Kind: stepTrace, Container: *ctr})
114		}
115		for _, h := range visiblePathHops(hops) {
116			steps = append(steps, pathStep{Kind: stepHop, Hop: h})
117		}
118		return steps
119	}
120	
121	// hopCell is the TTL of a hop row; empty for the local rows.
122	func (s pathStep) hopCell() string {
123		if s.Kind != stepHop {
124			return ""
125		}
126		return strconv.Itoa(s.Hop.TTL)
127	}
128	
129	// stepCell names the kind of row.
130	func (s pathStep) stepCell() string {
131		switch s.Kind {
132		case stepContainer:
133			return "container"
134		case stepNetwork:
135			return "network"
136		case stepBridge:
137			return "bridge"
138		case stepEngine:
139			return "engine"
140		case stepTrace:
141			return "trace"
142		case stepSource:
143			return "source"
144		case stepInterface:
145			return "interface"
146		case stepGateway:
147			return "gateway"
148		}
149		return s.Hop.Kind.String()
150	}
151	
152	// addressCell is the main text of the row.
153	func (s pathStep) addressCell() string {
154		switch s.Kind {
155		case stepContainer:
156			return s.Container.containerText()
157		case stepNetwork:
158			return s.Container.networkText()
159		case stepBridge:
160			return s.Container.Bridge
161		case stepEngine:
162			return s.Container.engineText()
163		case stepTrace:
164			return s.Container.traceText()
165		case stepSource:
166			if s.WSL.WSL2 {
167				return wslSourceText(s.WSL)
168			}
169			return sourceLabel
170		case stepInterface:
171			return s.Route.interfaceText()
172		case stepGateway:
173			return s.Route.gatewayText() + s.hostTag()
174		}
175		return addrOrDash(s.Hop.Addr) + s.hostTag()
176	}
177	
178	// hostTag is the Windows host label of a row marked by withWSL.
179	func (s pathStep) hostTag() string {
180		if s.WindowsHost {
181			return windowsHostTag
182		}
183		return ""
184	}
185	
186	// rttCell is the round-trip time of a hop that answered; "-" otherwise.
187	func (s pathStep) rttCell() string {
188		if s.Kind != stepHop {
189			return ""
190		}
191		if s.Hop.RTT <= 0 {
192			return "-"
193		}
194		return fmt.Sprintf("%.1f ms", float64(s.Hop.RTT)/float64(time.Millisecond))
195	}
196	
197	// interfaceText is the interface name, followed by the source address when known.
198	func (r pathRoute) interfaceText() string {
199		if r.NoRoute {
200			return routeNone
201		}
202		if !r.Known || (r.Interface == "" && !r.Source.IsValid()) {
203			return routeUndetermined
204		}
205		name := printable(r.Interface)
206		if name == "" {
207			name = "unnamed"
208		}
209		if !r.Source.IsValid() {
210			return name
211		}
212		return name + " (" + r.Source.String() + ")"
213	}
214	
215	// gatewayText is the gateway address, or says the destination is directly connected.
216	func (r pathRoute) gatewayText() string {
217		switch {
218		case r.NoRoute:
219			return gatewayNone
220		case !r.Known:
221			return routeUndetermined
222		case !r.Gateway.IsValid() || r.Gateway.IsUnspecified():
223			return gatewayDirect
224		}
225		return r.Gateway.String()
226	}
227	
228	// addrOrDash formats an address, or "-" when there is none.
229	func addrOrDash(a netip.Addr) string {
230		if !a.IsValid() {
231			return "-"
232		}
233		return a.String()
234	}
